  // Caller invariant: the CPU must already be out of reset.
  void apply_resume_from_qemu(const std::string& path)
  {
    hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width, PLATFORM::dmi_data_width>
      bus{platform.dmi, platform.clk.period()};
    hybrid_input_state_ = hybrid::load_state(path);
    // Stage V-register bytes into the fixed scratch region of RAM BEFORE
    // resume: ResumeDriver's Program-Buffer reload sweep issues vle8.v from
    // this region to repopulate v0..v31, so the bytes must be in place first.
    // Best-effort: mismatched RAM layouts throw, which is louder than silently
    // dropping V state.
    if ((hybrid_input_state_->flags & HYBRID_FLAG_V) != 0u) {
      hybrid::stage_v_to_scratch(*hybrid_input_state_,
                                 platform.main_memory.data);
    }
    // GPR block-load: stage x1..x31 into the scratch page so the resume
    // ld-sweep repopulates them in ~6 DM round-trips instead of 31 abstract
    // writes. Host memcpy is free. Gate on gpr_scratch_fits -- the same
    // condition ResumeDriver uses -- so when the V data fills the page we skip
    // staging (the abstract-write fallback runs) and never clobber v30/v31.
    if (hybrid::gpr_scratch_fits(hybrid_input_state_->vlenb))
      hybrid::stage_gpr_to_scratch(*hybrid_input_state_,
                                   platform.main_memory.data);
    // FPR block-load: stage f0..f31 just below the GPR block so the resume
    // fld-sweep repopulates them in ~6 DM round-trips instead of 32 abstract
    // writes. Gate on the FP flag and fpr_scratch_fits (tighter than the GPR
    // gate -- the FPR block sits lower in the page), so a full V page skips
    // staging and the abstract-write fallback runs.
    if ((hybrid_input_state_->flags & HYBRID_FLAG_FP) != 0u
        && hybrid::fpr_scratch_fits(hybrid_input_state_->vlenb))
      hybrid::stage_fpr_to_scratch(*hybrid_input_state_,
                                   platform.main_memory.data);
    // NOTE: the RESTORE csr_sweep stays OFF. A csrrw to a caps-supported but
    // read-only / WARL-illegal CSR raises cmderr in the Program Buffer, and a
    // batched sweep cannot tolerate a mid-batch fault the way the abstract path's
    // per-CSR clear_cmderr does. Restoring those CSRs is a no-op anyway (can't
    // write a read-only CSR), so restore keeps the abstract-tolerant path until a
    // per-CSR writability model can gate the sweep. The DRAIN sweep IS on (csrr
    // reads never fault for a readable CSR) -- see set_block_store_drain.
    hybrid::ResumeDriver driver(bus, v_scratch_gpa(),
                                hybrid::andes_caps_from_config());
    driver.set_gpr_block_load(true);
    driver.set_fpr_block_load(true);
    driver.resume(*hybrid_input_state_);
  }

  // Enables the vsim->QEMU handoff drain. After this is set, run() watches
  // committed PCs and on retire of a `csrw 0x7C0, *` exit-trigger drains
  // architectural state to `state_out_path` and returns kExitHandoffToQemu.
  //
  // When `exit_pc` is set, the trigger is populated by `add_pc_hit` (PC
  // mode) and the ELF scan is skipped: the binary need not contain a magic
  // csrwi marker. CSR mode and PC mode are mutually exclusive on a single
  // run -- callers pass exactly one form.
  void enable_hybrid_handoff(const std::string& elf_path,
                             const std::string& state_out_path,
                             std::optional<uint64_t> exit_pc = std::nullopt,
                             bool drain_minimal = false)
  {
    hybrid::CsrTrigger trigger;
    if (exit_pc) {
      trigger.add_pc_hit(*exit_pc, HYBRID_HANDOFF_EXIT);
      spdlog::info("hybrid: PC-trigger mode, exit_pc=0x{:x}", *exit_pc);
    } else {
      auto elf = LIEF::ELF::Parser::parse(elf_path);
      if (!elf)
        throw std::runtime_error(
          "enable_hybrid_handoff: failed to parse " + elf_path);
      for (const auto& seg: elf->segments()) {
        if (seg.type() != LIEF::ELF::SEGMENT_TYPES::PT_LOAD) continue;
        if ((static_cast<unsigned>(seg.flags()) & 1u) == 0u) continue;  // PF_X
        const auto content = seg.content();
        const std::span<const uint8_t> bytes{content.data(), content.size()};
        trigger.scan_buffer(bytes, seg.virtual_address());
      }
    }

    hybrid_dmi_bus_ = std::make_unique<
      hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width,
                            PLATFORM::dmi_data_width>>(platform.dmi,
                                                       platform.clk.period());
    hybrid_handoff_.emplace(std::move(trigger), *hybrid_dmi_bus_,
                            v_scratch_gpa(), hybrid::andes_caps_from_config());
    if (hybrid_input_state_)
      hybrid_handoff_->set_passthrough_input(*hybrid_input_state_);
    hybrid_handoff_->set_minimal_drain(drain_minimal);
    hybrid_handoff_->set_block_store_drain(true);
    hybrid_state_path_ = state_out_path;
  }

