280	// Read a 64-bit hart register (GPR / FPR / CSR by abstract regno) over DMI
281	// via an Abstract Command. Halts-and-reads contract: caller must have the
282	// hart in the halted state. Shared by StateDrain (drain at exit). If
283	// abstractcs.cmderr goes sticky after the command, the helper clears it and
284	// reports 0 rather than blocking the caller -- a missing CSR mirrors as zero
285	// instead of corrupting the adjacent field.
286	inline auto read_register_64_checked(DmiBus& bus, uint16_t regno,
287	                                     const char* poll_label
288	                                       = "read_register_64")
289	  -> std::optional<uint64_t>
290	{
291	  using RD = ResumeDriver;
292	  bus.write(RD::kCommand,
293	            access_register_command(regno, AarSize::Bits64, /*write=*/false));
294	  poll_until_clear(bus, RD::kAbstractcs, RD::kAbstractcsBusy, poll_label);
295	  const auto status = bus.read(RD::kAbstractcs);
296	  if ((status & RD::kAbstractcsCmderrMask) != 0u) {
297	    bus.write(RD::kAbstractcs, RD::kAbstractcsCmderrMask);
298	    return std::nullopt;
299	  }
300	  const uint64_t lo = bus.read(RD::kData0);
301	  const uint64_t hi = bus.read(RD::kData1);
302	  return lo | (hi << 32);
303	}
304	
305	inline auto read_register_64(DmiBus& bus, uint16_t regno,
306	                             const char* poll_label = "read_register_64")
307	  -> uint64_t
308	{
309	  return read_register_64_checked(bus, regno, poll_label).value_or(0u);
310	}
