1	// StateDrain halts the hart via the Debug Module and populates a
2	// hybrid_state_v1 with the architectural register file. Reuses
3	// ResumeDriver's DM register constants and DmiBus interface.
4	
5	#pragma once
6	
7	#include "hybrid/abstract_command.hpp"
8	#include "hybrid/dmi_poll.hpp"
9	#include "hybrid/resume_driver.hpp"
10	#include "hybrid/state_abi.h"
11	
12	#include <cstdint>
13	
14	namespace hybrid
15	{
16	
17	class StateDrain
18	{
19	public:
20	  using RD = ResumeDriver;
21	
22	  explicit StateDrain(DmiBus& bus) : bus_{bus} {}
23	
24	  // Drain x1..x31 + PC. FP/CSR/V slots remain zero; merge them in via
25	  // drain_with_passthrough when the QEMU 1 snapshot is available.
26	  auto drain() -> hybrid_state_v1
27	  {
28	    hybrid_state_v1 state{};
29	    state.magic   = HYBRID_STATE_MAGIC;
30	    state.version = HYBRID_STATE_VERSION;
31	    state.flags   = HYBRID_FLAG_RV64;
32	    halt_and_capture_pc_priv(state);
33	
34	    for (uint16_t i = 1; i < 32; ++i)
35	      state.gpr[i] = read_register_64(bus_, regno_gpr(i), "StateDrain GPR");
36	
37	    return state;
38	  }
39	
40	  // Returns the input snapshot with x1..x31 and PC overwritten by a fresh
41	  // DM read. When HYBRID_FLAG_FP is set, also freshly reads f0..f31 + fcsr
42	  // (L20) so post-vsim FP modifications are captured (otherwise the stale
43	  // QEMU 1 snapshot leaks into the drained state).
44	  // mcycle/minstret are always refreshed (F-T2.4): the vsim phase's
45	  // contribution would otherwise be discarded as the passthrough preserves
46	  // QEMU1's pre-handoff value.
47	  auto drain_with_passthrough(const hybrid_state_v1& input) -> hybrid_state_v1
48	  {
49	    auto state = input;
50	    halt_and_capture_pc_priv(state);  // L6: pc + privilege at the exit halt
51	
52	    // GPRs/FPRs: one abstract register read each. Abstract-only by design,
53	    // like the resume side -- the Program Buffer is reserved for state the
54	    // abstract command space cannot reach.
55	    for (uint16_t i = 1; i < 32; ++i)
56	      state.gpr[i] = read_register_64(bus_, regno_gpr(i), "StateDrain GPR");
57	
58	    if (input.flags & HYBRID_FLAG_FP) {
59	      for (uint16_t i = 0; i < 32; ++i)
60	        state.fpr[i] = read_register_64(bus_, regno_fpr(i), "StateDrain FPR");
61	      // L20: fcsr (frm + sticky fflags) accumulated by the vsim phase.
62	      state.fcsr = read_register_64(bus_, regno_csr(RD::kCsrFcsr));
63	    }
64	
65	    // L23: mscratch round-trips now (ResumeDriver restores it), so re-read it
66	    // from the hart -- otherwise an in-ROI write to the software scratch CSR is
67	    // dropped and the stale QEMU1 value passes through into the drained state.
68	    state.mscratch = read_register_64(bus_, regno_csr(RD::kCsrMscratch));
69	
70	    // L24: the writable M-mode trap/interrupt CSRs round-trip too (ResumeDriver
71	    // restores them), so re-read them -- an in-ROI write must reach the drained
72	    // state instead of the stale QEMU1 passthrough value.
73	    state.mepc   = read_register_64(bus_, regno_csr(RD::kCsrMepc));
74	    state.mcause = read_register_64(bus_, regno_csr(RD::kCsrMcause));
75	    state.mtval  = read_register_64(bus_, regno_csr(RD::kCsrMtval));
76	    state.mie    = read_register_64(bus_, regno_csr(RD::kCsrMie));
77	    state.mip    = read_register_64(bus_, regno_csr(RD::kCsrMip));
78	
79	    state.mcycle   = read_register_64(bus_, regno_csr(RD::kCsrMcycle));
80	    state.minstret = read_register_64(bus_, regno_csr(RD::kCsrMinstret));
81	
82	    return state;
83	  }
84	
85	private:
86	  // Halt the hart and capture the two control fields every drain path needs:
87	  // privilege (dcsr.prv, L6) and PC (dpc). Header fields and the register
88	  // blocks are filled by the caller, so drain() and drain_with_passthrough
89	  // share one halt + prologue. dmactive must transition 0->1 in its own write
90	  // before haltreq is honored (RISC-V Debug Spec), then wait for allhalted.
91	  void halt_and_capture_pc_priv(hybrid_state_v1& state)
92	  {
93	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive);
94	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive | RD::kDmcontrolHaltreq);
95	    poll_until_set(bus_, RD::kDmstatus, RD::kDmstatusAllhalted,
96	                   "StateDrain halt");
97	
98	    state.priv = read_register_64(bus_, regno_csr(RD::kCsrDcsr),
99	                                  "StateDrain DCSR") & 0x3u;
100	    state.pc = read_register_64(bus_, regno_csr(RD::kCsrDpc), "StateDrain DPC");
101	  }
102	
103	  DmiBus& bus_;
104	};
105	
106	}  // namespace hybrid
