// Pure-byte-copy helpers that move state.vreg[] in and out of the V scratch
// region. L26: the scratch is the TOP kVScratchBytes of the mapped RAM span
// (v_scratch_gpa = ram_base + ram_size - kVScratchBytes), not a fixed GPA.
// The host stager copies span-relative (the scratch is the span's top page),
// so it needs no ram_base; ram_base only enters the GUEST address the
// Program-Buffer sweep uses, which is what v_scratch_gpa() returns.
// The unit tests assert: bytes round-trip with no padding loss, the GPA
// tracks span size + base, and a span smaller than one scratch page throws.

#include "hybrid/state_abi.h"
#include "hybrid/v_regfile_xfer.hpp"

#define DOCTEST_CONFIG_IMPLEMENT_WITH_MAIN
#include <doctest.h>

#include <algorithm>
#include <cstdint>
#include <cstring>
#include <vector>

TEST_CASE("v_regfile_xfer: stage packs registers contiguously at vlenb stride")
{
  // The scratch is vlenb-PACKED (register r at offset r*vlenb, no wire-format
  // padding gap) so 8 consecutive registers form one LMUL=8 group for the
  // Program-Buffer sweep. Fill only the meaningful (first vlenb) bytes of each
  // wire slot; leave the padding zero (matches what the QEMU plugin drains).
  hybrid_state_v1 in{};
  in.vlenb = 64;  // VLEN=512
  for (int r = 0; r < 32; ++r)
    for (size_t b = 0; b < in.vlenb; ++b)
      in.vreg[r * HYBRID_VLEN_BYTES_MAX + b] =
          static_cast<uint8_t>((r * 64 + b) & 0xff);

  std::vector<uint8_t> ram(static_cast<size_t>(128) * 1024 * 1024);
  hybrid::stage_v_to_scratch(in, ram);

  // L26: the scratch window is the TOP page of the span, not a fixed GPA.
  // Each register sits at off + r*vlenb, contiguous (NOT the 128-byte wire span).
  const size_t off = ram.size() - hybrid::kVScratchBytes;
  for (int r = 0; r < 32; ++r)
    CHECK(std::memcmp(ram.data() + off + static_cast<size_t>(r) * in.vlenb,
                      in.vreg + r * HYBRID_VLEN_BYTES_MAX, in.vlenb) == 0);

  // Round-trip: read into a zero-init state; meaningful bytes return and the
  // wire-slot padding stays zero (so the full 128-byte slots equal `in`).
  hybrid_state_v1 out{};
  out.vlenb = in.vlenb;
  hybrid::read_v_from_scratch(out, ram);
  CHECK(std::memcmp(out.vreg, in.vreg, hybrid::kVScratchBytes) == 0);
}

TEST_CASE("for_each_transport_csr: walks all Andes+PMA+M-ext CSRs in canonical "
          "order (caps=all), addr precedes cfg")
{
  hybrid_state_v1 in{};
  in.flags = HYBRID_FLAG_RV64 | HYBRID_FLAG_ANDES | HYBRID_FLAG_M_EXT;

  std::vector<uint16_t> addrs;
  hybrid::for_each_transport_csr(in, hybrid::AndesCaps::all(),
    [&](uint16_t addr, const uint64_t&) { addrs.push_back(addr); });

  // 13 Andes scalars + 16 pmaaddr + 2 pmacfg + 51 M-ext = 82 CSRs.
  CHECK(addrs.size() == 82u);
  // Canonical order: PMA ADDR (0xBD0..) before PMA CFG (0xBC0/0xBC2), so the
  // restore's TOR/NAPOT cfg consumes the addr already in place.
  const auto addr0 = std::find(addrs.begin(), addrs.end(),
                               uint16_t(HYBRID_PMA_ADDR0_CSR));
  const auto cfg0  = std::find(addrs.begin(), addrs.end(),
                               uint16_t(HYBRID_PMA_CFG0_CSR));
  REQUIRE(addr0 != addrs.end());
  REQUIRE(cfg0 != addrs.end());
  CHECK(addr0 < cfg0);
}

TEST_CASE("for_each_transport_csr: honors the block flags (M-ext only, no Andes)")
{
  hybrid_state_v1 in{};
  in.flags = HYBRID_FLAG_RV64 | HYBRID_FLAG_M_EXT;  // no ANDES
  in.andes.mxstatus = 0xAAAA;  // must NOT be walked
  in.m_ext.menvcfg  = 0xBBBB;  // must be walked

  bool saw_mxstatus = false, saw_menvcfg = false;
  hybrid::for_each_transport_csr(in, hybrid::AndesCaps::all(),
    [&](uint16_t, const uint64_t& field) {
      if (field == 0xAAAA) saw_mxstatus = true;
      if (field == 0xBBBB) saw_menvcfg  = true;
    });

  CHECK(saw_menvcfg);        // M-ext walked
  CHECK_FALSE(saw_mxstatus); // Andes block skipped
}

TEST_CASE("for_each_transport_csr: honors caps -- gated CSR skipped, "
          "ALWAYS-gated CSR still walked")
{
  hybrid_state_v1 in{};
  in.flags = HYBRID_FLAG_RV64 | HYBRID_FLAG_ANDES;

  std::vector<uint16_t> addrs;
  hybrid::for_each_transport_csr(in, hybrid::AndesCaps::none(),
    [&](uint16_t addr, const uint64_t&) { addrs.push_back(addr); });

  // 0x7C4 mxstatus is ALWAYS-gated: walked even with caps none().
  CHECK(std::find(addrs.begin(), addrs.end(), uint16_t(0x7C4)) != addrs.end());
  // 0x801 ucode is DSP-gated: skipped when the gate is off.
  CHECK(std::find(addrs.begin(), addrs.end(), uint16_t(0x801)) == addrs.end());
}

TEST_CASE("v_regfile_xfer: v_scratch_gpa = ram_base + ram_size - kVScratchBytes")
{
  // The single source of truth for the scratch's GUEST address: the top page.
  CHECK(hybrid::v_scratch_gpa(0x0ull, 128ull * 1024 * 1024)
        == 128ull * 1024 * 1024 - hybrid::kVScratchBytes);            // 0x07FFF000
  CHECK(hybrid::v_scratch_gpa(0x0ull, 0x80000000ull)
        == 0x80000000ull - hybrid::kVScratchBytes);                   // 0x7FFFF000
  // Non-zero base shifts the GPA by the base.
  CHECK(hybrid::v_scratch_gpa(0x80000000ull, 64ull * 1024 * 1024)
        == 0x80000000ull + 64ull * 1024 * 1024 - hybrid::kVScratchBytes);
  // L11: 128 bytes per register (VLEN ceiling 1024) -> 4 KiB scratch.
  CHECK(hybrid::kVScratchBytes == static_cast<size_t>(32) * 128);
}

TEST_CASE("v_regfile_xfer: throws when the RAM span is smaller than one scratch page")
{
  std::vector<uint8_t> ram(hybrid::kVScratchBytes - 1);  // one byte too small
  hybrid_state_v1 s{};
  CHECK_THROWS(hybrid::stage_v_to_scratch(s, ram));
  CHECK_THROWS(hybrid::read_v_from_scratch(s, ram));
}

// B7: doctest for the QEMU-plugin V-drain decision function.
//
// The plugin's V-state drain used to gate on `v->vlenb` (the register
// handle truthiness) AND `s.vlenb > 0`. The combination silently omits
// the V block whenever the stub advertises some V state but not vlenb,
// confusing "stub broke" with "V disabled at runtime". This test pins
// the four-case truth table: SKIP when no V at all, ABORT when partial,
// SKIP when V advertised but disabled (vlenb=0), OK otherwise.

#define DOCTEST_CONFIG_IMPLEMENT_WITH_MAIN
#include "doctest.h"

#include "hybrid/state_abi.h"  // HYBRID_VLEN_BYTES_MAX (the L11 ceiling)
#include "hybrid/v_drain_policy.h"

TEST_CASE("no V advertised at all -> SKIP")
{
  CHECK(hybrid_v_drain_policy(/*has_vlenb=*/0, /*has_other_v=*/0,
                              /*vlenb_value=*/0)
        == HYBRID_V_DRAIN_SKIP);
}

TEST_CASE("vlenb missing but vtype/vl/etc advertised -> ABORT")
{
  // The "broken stub" case the original gate hid. Don't silently emit a
  // zero-filled V block: the resume side then restores garbage V state.
  CHECK(hybrid_v_drain_policy(/*has_vlenb=*/0, /*has_other_v=*/1,
                              /*vlenb_value=*/0)
        == HYBRID_V_DRAIN_ABORT);
}

TEST_CASE("vlenb advertised but value=0 -> SKIP (V disabled at runtime)")
{
  // QEMU may expose the V feature in XML even when V is not enabled in
  // the CPU at runtime; vlenb then reads 0. Treat as "no V live".
  CHECK(hybrid_v_drain_policy(/*has_vlenb=*/1, /*has_other_v=*/1,
                              /*vlenb_value=*/0)
        == HYBRID_V_DRAIN_SKIP);
}

TEST_CASE("vlenb advertised, value>0 -> OK")
{
  CHECK(hybrid_v_drain_policy(/*has_vlenb=*/1, /*has_other_v=*/1,
                              /*vlenb_value=*/16)
        == HYBRID_V_DRAIN_OK);
  CHECK(hybrid_v_drain_policy(/*has_vlenb=*/1, /*has_other_v=*/1,
                              /*vlenb_value=*/64)
        == HYBRID_V_DRAIN_OK);
}

TEST_CASE("L11: vlenb at the wire-format ceiling -> OK (VLEN 1024)")
{
  CHECK(hybrid_v_drain_policy(/*has_vlenb=*/1, /*has_other_v=*/1,
                              /*vlenb_value=*/HYBRID_VLEN_BYTES_MAX)
        == HYBRID_V_DRAIN_OK);
}

TEST_CASE("L11: vlenb above the wire-format ceiling -> ABORT, not a "
          "silent clamp")
{
  // The old drain clamped the copy to HYBRID_VLEN_BYTES_MAX and dropped
  // the upper bytes of every V register without a word. Refuse instead:
  // the state file cannot represent this engine's V regfile.
  CHECK(hybrid_v_drain_policy(/*has_vlenb=*/1, /*has_other_v=*/1,
                              /*vlenb_value=*/HYBRID_VLEN_BYTES_MAX + 1)
        == HYBRID_V_DRAIN_ABORT);
  CHECK(hybrid_v_drain_policy(/*has_vlenb=*/1, /*has_other_v=*/1,
                              /*vlenb_value=*/2 * HYBRID_VLEN_BYTES_MAX)
        == HYBRID_V_DRAIN_ABORT);
}

TEST_CASE("vlenb advertised alone (no other V) is still ABORT-equivalent: "
          "policy treats vlenb-only as no V context")
{
  // Edge case: stub advertises vlenb but no other V regs. This is
  // unusual; treat as SKIP since we have no V data to actually drain.
  // (Documented behaviour, not a runtime failure mode QEMU emits.)
  CHECK(hybrid_v_drain_policy(/*has_vlenb=*/1, /*has_other_v=*/0,
                              /*vlenb_value=*/16)
        == HYBRID_V_DRAIN_SKIP);
}

// ResumeDriver translates a hybrid_state_v1 into a sequence of DMI register
// ops against the RISC-V Debug Module. The orchestration is testable in
// isolation by injecting a recording bus.

#include "hybrid/abstract_command.hpp"
#include "hybrid/andes_caps.hpp"
#include "hybrid/program_buffer.hpp"
#include "hybrid/resume_driver.hpp"
#include "hybrid/state_abi.h"
#include "hybrid/v_regfile_xfer.hpp"

#define DOCTEST_CONFIG_IMPLEMENT_WITH_MAIN
#include <doctest.h>

#include <cstdint>
#include <deque>
#include <optional>
#include <set>
#include <unordered_map>
#include <vector>

namespace {

// DMI register addresses from RISC-V Debug Spec 1.0.
constexpr uint8_t kDmcontrol  = 0x10;
constexpr uint8_t kDmstatus   = 0x11;
constexpr uint8_t kAbstractcs = 0x16;
constexpr uint8_t kCommand    = 0x17;
constexpr uint8_t kData0      = 0x04;
constexpr uint8_t kData1      = 0x05;

// CSR numbers from Debug Spec.
constexpr uint16_t kCsrDpc  = 0x7B1;
constexpr uint16_t kCsrDcsr = 0x7B0;

// L26: the V scratch GPA is a runtime value (mmap top page) passed to the
// driver. Tests pass this distinctive stand-in and assert the sweep uses it.
constexpr uint64_t kScratch = 0x07FFF000ull;  // 128 MiB mmap top page

struct DmiOp
{
  enum class Kind
  {
    Write,
    Read,
  };
  Kind kind;
  uint8_t reg;
  uint32_t value;  // for writes only
};

struct RecordingBus final : hybrid::DmiBus
{
  std::vector<DmiOp> ops;

  // Test-controlled response values for reads.
  uint32_t dmstatus_value = 0;       // bit 9: allhalted, bit 17: allresumeack
  uint32_t abstractcs_value = 0;     // fallback when queue is empty
  std::deque<uint32_t> abstractcs_queue; // queued reads drain first

  // When set, an abstract write-COMMAND to this CSR regno raises a sticky
  // cmderr (cleared by the W1C abstractcs write the driver issues on its PB
  // fallback). Models real hardware and -- unlike positional queueing -- is
  // robust to however many unrelated abstract ops precede the targeted write.
  std::optional<uint16_t> fail_csr_write;

  // One-shot: when true, the NEXT kExecProgbufCmd write raises sticky cmderr
  // (so exec_progbuf throws after its post-exec abstractcs poll). The flag
  // re-arms to false after firing - tests can flip it back on to fail a
  // later PB exec.
  bool fail_next_pb_exec = false;

  // Mini register file: abstract write-COMMANDs latch the staged DATA0/DATA1
  // into regfile[regno]; abstract read-COMMANDs load it back so read-modify-
  // write-verify sequences observe their own writes. Regnos in warl_ignore
  // model WARL fields the hart pins (the write is recorded but discarded),
  // e.g. dcsr.prv on a core without S/U modes.
  std::unordered_map<uint16_t, uint64_t> regfile;
  std::set<uint16_t> warl_ignore;

  void write(uint8_t reg, uint32_t value) override
  {
    ops.push_back({DmiOp::Kind::Write, reg, value});
    if (reg == kData0) staged_data0_ = value;
    if (reg == kData1) staged_data1_ = value;
    if (reg == kAbstractcs && (value & kCmderrMask) != 0u)
      cmderr_sticky_ = false;  // W1C clear
    if (reg == kCommand && fail_csr_write) {
      const auto regno    = static_cast<uint16_t>(value & 0xFFFFu);
      const bool is_write = ((value >> 16) & 1u) != 0u;
      if (is_write && regno == hybrid::regno_csr(*fail_csr_write))
        cmderr_sticky_ = true;
    }
    if (reg == kCommand && value != hybrid::kExecProgbufCmd) {
      const auto regno    = static_cast<uint16_t>(value & 0xFFFFu);
      const bool is_write = ((value >> 16) & 1u) != 0u;
      if (is_write) {
        if (!warl_ignore.count(regno))
          regfile[regno] = (uint64_t{staged_data1_} << 32) | staged_data0_;
      } else {
        const auto it = regfile.find(regno);
        const uint64_t v = (it == regfile.end()) ? 0u : it->second;
        pending_data0_ = static_cast<uint32_t>(v);
        pending_data1_ = static_cast<uint32_t>(v >> 32);
      }
    }
    if (reg == kCommand && value == hybrid::kExecProgbufCmd
        && fail_next_pb_exec) {
      cmderr_sticky_ = true;
      fail_next_pb_exec = false;
    }
  }

  auto read(uint8_t reg) -> uint32_t override
  {
    ops.push_back({DmiOp::Kind::Read, reg, 0});
    if (reg == kDmstatus) return dmstatus_value;
    if (reg == kData0)   return pending_data0_;
    if (reg == kData1)   return pending_data1_;
    if (reg == kAbstractcs) {
      if (cmderr_sticky_) return kCmderrMask;
      if (!abstractcs_queue.empty()) {
        auto v = abstractcs_queue.front();
        abstractcs_queue.pop_front();
        return v;
      }
      return abstractcs_value;
    }
    return 0;
  }

private:
  static constexpr uint32_t kCmderrMask = 0x7u << 8;
  bool cmderr_sticky_ = false;
  uint32_t staged_data0_  = 0;
  uint32_t staged_data1_  = 0;
  uint32_t pending_data0_ = 0;
  uint32_t pending_data1_ = 0;
};

auto rv64_state(uint64_t pc, uint64_t x10) -> hybrid_state_v1
{
  hybrid_state_v1 s{};
  s.magic = HYBRID_STATE_MAGIC;
  s.version = HYBRID_STATE_VERSION;
  s.flags = HYBRID_FLAG_RV64;
  s.pc = pc;
  s.priv = 3;
  s.gpr[10] = x10;
  return s;
}

auto find_write(const std::vector<DmiOp>& ops, uint8_t reg)
  -> std::vector<uint32_t>
{
  std::vector<uint32_t> values;
  for (const auto& op : ops)
    if (op.kind == DmiOp::Kind::Write && op.reg == reg)
      values.push_back(op.value);
  return values;
}

auto count_writes_to(const std::vector<DmiOp>& ops, uint8_t reg) -> std::size_t
{
  std::size_t n = 0;
  for (const auto& op : ops)
    if (op.kind == DmiOp::Kind::Write && op.reg == reg) ++n;
  return n;
}

